//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)

scwin.fn_GetPar, scwin.fn_SetPar, scwin.strCdSch;
scwin.fr_SecuGrpId; //증권그룹ID
scwin.fr_mktTpCd; // 유가종목, 코스닥종목, 유가+코스닥전체종목 조회구분값 
scwin.vScrenID = "ULDSTF05108.xml";
scwin.strSch;

scwin.onpageload = function() {
    scwin.init();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = async function() {
    //var url = "/KindStk.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listIsurInst&inputMessageId=KIND_STK_PRELIST_ISUR_INST_OUT";
    //url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    //url += "&COM_NM=" + txb_COM_NM.getValue();
    //url += "&SECUGRP_ID=" + scwin.fr_SecuGrpId;
    //url += "&SPOT_ISU_TRD_MKT_TP_CD=" + scwin.fr_mktTpCd;
    //dts_IsurInst.DataID = encodeURI(url);
    //dts_IsurInst.reset();

    var param = {
        isurCd : txb_ISUR_CD.getValue(),
        comNm : txb_COM_NM.getValue(),
        secugrpId : scwin.fr_SecuGrpId,
        spotIsuTrdMktTpCd : scwin.fr_mktTpCd
    }
    const sbmOptions = {
        id: "sbm_selectListPreListingKindstk",
        action: "/api/listing/common/pop/issur/select-list-prelisting-kindstk",
        method: "get",
        ref: "dlt_isurInstRes",
        target: "dlt_isurInstRes=body",
        isProcessMsg: false
    };
    let res = await $c.sbm.executeDynamic(sbmOptions, param);

    txb_TotCnt.setValue(dlt_isurInstRes.getTotalRow());

    // 초기1회 초기값으로 설정된 회사코드를 검색한다.
    if (scwin.strCdSch != "") {
        for (var i = 1; i <= dlt_isurInstRes.getTotalRow(); i++) {
            if (scwin.strCdSch == dlt_isurInstRes.getCellData(i, 1)) {
                dlt_isurInstRes.setRowPosition(i, 0);
                break;
            }
        }
        scwin.strCdSch = "";
    }
};
scwin.txb_COM_NM_onkeydown = function(e) {
    if (e.keyCode == 13) {
        scwin.fn_list_sync();
    }
};
scwin.dts_IsurInst_OnLoadError = function() {
    $c.stf.alert_error(dts_IsurInst);
};
/* scwin.dts_IsurInst_OnLoadCompleted = function(rowcount) {
    if (dts_IsurInst.errorMsg) {
        $c.win.alert(dts_IsurInst.errorMsg);
    } else {
        txb_TotCnt.setValue("총 " + rowcount + " 건");

        // 초기1회 초기값으로 설정된 회사코드를 검색한다.
        if (scwin.strCdSch != "") {
            for (var i = 1; i <= dts_IsurInst.getTotalRow(); i++) {
                if (scwin.strCdSch == dts_IsurInst.getCellData(i, 1)) {
                    dts_IsurInst.setRowPosition(i, 0);
                    break;
                }
            }
            scwin.strCdSch = "";
        }
    }
}; */
scwin.grd_IsuInst_OnDblClick = async function(row, colid) {
    var arrPar = new Array();
    if (scwin.fn_SetPar != undefined) {
        arrPar[0] = {
            ISUR_CD: dlt_isurInstRes.getCellData(row, "isurCd"),
            COM_NM: dlt_isurInstRes.getCellData(row, "comNm"),
            LIST_DD: dlt_isurInstRes.getCellData(row, "listDd"),
            LIST_BZ_SEQ: dlt_isurInstRes.getCellData(row, "listBzSeq"),
            DBCLICKYN: "Y"
        };
        scwin.fn_SetPar(arrPar);
    }
    await $c.win.closePopup();$c.win.closePopup();
};
scwin.img_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.img_Close_onclick = async function() {
    await $c.win.closePopup();
};
scwin.init = function() {
    window.document.body.scroll = "no";
    var arrPar = new Array();
    /***************************************
    opener에  fn_GetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 업종조회후  최초 지정 코드값이 없는 상태
    opener에  fn_SetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 선택한 코드값과 코드명칭을 지정하지 않는다.
    ***************************************/
    var parentWin = $c.win.getParent();
    scwin.fn_GetPar = parentWin.scwin.fn_GetPar;
    scwin.fn_SetPar = parentWin.scwin.fn_SetPar;
    //alert('[fr_SearchTyp]'+fr_SearchTyp);

    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(arrPar);
        scwin.strSch = (arrPar.length >= 1 ? arrPar[0] : "");
        scwin.fr_SecuGrpId = (arrPar.length >= 3 ? arrPar[2] : "");
        scwin.fr_mktTpCd = (arrPar.length >= 4 ? arrPar[3] : "");
    }
    scwin.fn_list_sync();
};
